#include <windows.h>
#include <mfapi.h>
#include <mfidl.h>
#include <mfreadwrite.h>
#include <wrl/client.h>
#include <cmath>
#include <filesystem>
#include <iostream>
#include <stdexcept>
#include <string>
using Microsoft::WRL::ComPtr;
void check(HRESULT hr){if(FAILED(hr))throw std::runtime_error("Media Foundation status "+std::to_string(static_cast<unsigned>(hr)));}
int main(int argc,char** argv){try{if(argc!=2)return 1;check(CoInitializeEx(nullptr,COINIT_MULTITHREADED));check(MFStartup(MF_VERSION));const auto path=std::filesystem::absolute(std::filesystem::u8path(argv[1]));ComPtr<IMFAttributes> attrs;check(MFCreateAttributes(&attrs,2));check(attrs->SetGUID(MF_TRANSCODE_CONTAINERTYPE,MFTranscodeContainerType_MPEG4));ComPtr<IMFSinkWriter> writer;check(MFCreateSinkWriterFromURL(path.c_str(),nullptr,attrs.Get(),&writer));ComPtr<IMFMediaType> out;check(MFCreateMediaType(&out));check(out->SetGUID(MF_MT_MAJOR_TYPE,MFMediaType_Audio));check(out->SetGUID(MF_MT_SUBTYPE,MFAudioFormat_AAC));check(out->SetUINT32(MF_MT_AUDIO_NUM_CHANNELS,2));check(out->SetUINT32(MF_MT_AUDIO_SAMPLES_PER_SECOND,48000));check(out->SetUINT32(MF_MT_AUDIO_BITS_PER_SAMPLE,16));check(out->SetUINT32(MF_MT_AUDIO_AVG_BYTES_PER_SECOND,24000));check(out->SetUINT32(MF_MT_AAC_PAYLOAD_TYPE,0));check(out->SetUINT32(MF_MT_AAC_AUDIO_PROFILE_LEVEL_INDICATION,0x29));DWORD stream=0;check(writer->AddStream(out.Get(),&stream));ComPtr<IMFMediaType> input;check(MFCreateMediaType(&input));check(input->SetGUID(MF_MT_MAJOR_TYPE,MFMediaType_Audio));check(input->SetGUID(MF_MT_SUBTYPE,MFAudioFormat_PCM));check(input->SetUINT32(MF_MT_AUDIO_NUM_CHANNELS,2));check(input->SetUINT32(MF_MT_AUDIO_SAMPLES_PER_SECOND,48000));check(input->SetUINT32(MF_MT_AUDIO_BITS_PER_SAMPLE,16));check(input->SetUINT32(MF_MT_AUDIO_BLOCK_ALIGNMENT,4));check(input->SetUINT32(MF_MT_AUDIO_AVG_BYTES_PER_SECOND,192000));check(writer->SetInputMediaType(stream,input.Get(),nullptr));check(writer->BeginWriting());
for(unsigned at=0;at<48000;){unsigned count=std::min(1024U,48000-at);ComPtr<IMFMediaBuffer> buffer;check(MFCreateMemoryBuffer(count*4,&buffer));BYTE* bytes=nullptr;check(buffer->Lock(&bytes,nullptr,nullptr));auto* values=reinterpret_cast<short*>(bytes);for(unsigned i=0;i<count;++i){values[i*2]=static_cast<short>(std::sin((at+i)*6.283185307179586*440/48000)*9000);values[i*2+1]=static_cast<short>(std::sin((at+i)*6.283185307179586*660/48000)*6000);}check(buffer->Unlock());check(buffer->SetCurrentLength(count*4));ComPtr<IMFSample> sample;check(MFCreateSample(&sample));check(sample->AddBuffer(buffer.Get()));check(sample->SetSampleTime(static_cast<LONGLONG>(at)*10000000/48000));check(sample->SetSampleDuration(static_cast<LONGLONG>(count)*10000000/48000));check(writer->WriteSample(stream,sample.Get()));at+=count;}
check(writer->Finalize());writer.Reset();ComPtr<IMFSourceReader> reader;check(MFCreateSourceReaderFromURL(path.c_str(),nullptr,&reader));ComPtr<IMFMediaType> decoded;check(MFCreateMediaType(&decoded));check(decoded->SetGUID(MF_MT_MAJOR_TYPE,MFMediaType_Audio));check(decoded->SetGUID(MF_MT_SUBTYPE,MFAudioFormat_Float));check(reader->SetCurrentMediaType(MF_SOURCE_READER_FIRST_AUDIO_STREAM,nullptr,decoded.Get()));unsigned long long frames=0;for(;;){DWORD flags=0;ComPtr<IMFSample> sample;check(reader->ReadSample(MF_SOURCE_READER_FIRST_AUDIO_STREAM,0,nullptr,&flags,nullptr,&sample));if(sample){ComPtr<IMFMediaBuffer> buffer;check(sample->ConvertToContiguousBuffer(&buffer));DWORD length=0;check(buffer->GetCurrentLength(&length));frames+=length/8;}if(flags&MF_SOURCE_READERF_ENDOFSTREAM)break;}
std::cout<<"frames="<<frames<<" pathBytes="<<std::filesystem::file_size(path)<<"\n";return frames>=48000&&frames<=50112?0:2;
}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 3;}}
